templates.template:
.account-header {
    padding-left: 10px;
}

.account-name {
    font-size: 1.5em;
    font-weight: bold;
}

a.account-create {
    float: right;
    margin-top: -30px;
    margin-right: 12px;
}

.no-characters {
    color: @xf-textColor;
    margin: 5px;
    text-align: center;
    float: left;
    width: 325px;
    border: 1px solid xf-intensify(@xf-contentBg, 15%);
    background-color: xf-intensify(@xf-contentBg, 5%);
    padding: 10px 0;
    border-radius: @xf-borderRadiusMedium;
}

.character {
    color: @xf-textColor;
    margin: 5px 0 5px 5px;
    text-align: center;
    float: left;
    width: 160px;
    border: 1px solid xf-intensify(@xf-contentBg, 15%);
    background-color: xf-intensify(@xf-contentBg, 5%);
    padding: 12px 8px 8px 8px;
    border-radius: @xf-borderRadiusMedium;
    box-shadow: 0 2px 6px rgba(0,0,0,0.25);
    transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;
}

.character:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 10px rgba(0,0,0,0.35);
    border-color: xf-intensify(@xf-contentBg, 25%);
}

.character h4 {
    margin: 0 0 5px 0;
    font-size: 14px;
    font-weight: 700;
    color: @xf-textColor;
}

.character h5 {
    margin: 0 0 4px 0;
    font-size: 11px;
    font-weight: normal;
    color: @xf-textColorMuted;
}

.account-management-header {
    margin-bottom: 10px;
    background-color: @xf-contentBg;
    border: 1px solid @xf-borderColor;
    height: 60px;
    padding-top: 13px;
    border-radius: @xf-borderRadiusMedium;
}

a.account-reset-pw {
    float: right;
}

button.account-create {
    margin-right: 10px;
}

#login_accounts .block {
    margin-bottom: 15px;
}

.character-actions {
    margin-top: 5px;
}

.character-actions .button {
    font-size: 11px;
    padding: 3px 8px;
    height: auto;
    line-height: 1.2;
}

document.addEventListener('DOMContentLoaded', function() {
    !function($, window, document, _undefined)
    {
        "use strict";

        XF.EqemuLogin_CreateAccount = XF.Element.newHandler({

            options: {},

            init: function()
            {
                const $form = this.$target;
                $form.on('ajax-submit:response', $.proxy(this, 'ajaxResponse'));
            },

            ajaxResponse: function(e, data)
            {
                $("#login_accounts").prepend(data.template);
                $('.account-count').text(function(i,txt){ return parseInt(txt,10) + 1; })
            }
        });

        XF.Element.register('create-account', 'XF.EqemuLogin_CreateAccount');
    }(window.jQuery, window, document);
});
